// GlitchSAT, ext/opentitan (own code, Apache-2.0). Not OpenTitan code.
//
// Stand-in for OpenTitan's abstract primitive `prim_flop`. In an OpenTitan build this module is
// generated by the primgen tool and selects a technology implementation. Here it always selects
// the generic implementation (prim_generic_flop, an asynchronous active-low reset flop), which is
// what OpenTitan's own AES Yosys flow does with `sed` (hw/ip/aes/pre_syn/syn_yosys.sh).
module prim_flop #(
  parameter int               Width      = 1,
  parameter logic [Width-1:0] ResetValue = 0
) (
  input                    clk_i,
  input                    rst_ni,
  input        [Width-1:0] d_i,
  output logic [Width-1:0] q_o
);

  prim_generic_flop #(
    .Width      (Width),
    .ResetValue (ResetValue)
  ) u_impl (
    .clk_i  (clk_i),
    .rst_ni (rst_ni),
    .d_i    (d_i),
    .q_o    (q_o)
  );

endmodule
